changeSet.sql:
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

CREATE TABLE app_user (
    id uuid PRIMARY KEY,
    display_name varchar(100) NOT NULL
);

CREATE TABLE club (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(200) NOT NULL UNIQUE,
    display_name varchar(200)
);

CREATE TABLE player (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(200) NOT NULL UNIQUE,
    display_name varchar(200),
    alias_of_player_id uuid REFERENCES player(id) ON DELETE SET NULL,
    search_vector tsvector GENERATED ALWAYS AS (
        to_tsvector('simple'::regconfig,
            coalesce(name, '') || ' ' || coalesce(display_name, '')
        )
    ) STORED,
    CONSTRAINT player_alias_not_self
        CHECK (alias_of_player_id IS NULL OR alias_of_player_id != id)
);
CREATE INDEX player_search_vector_idx ON player USING gin (search_vector);
CREATE UNIQUE INDEX player_alias_of_uniq ON player (alias_of_player_id)
    WHERE alias_of_player_id IS NOT NULL;
CREATE INDEX i_player__name_trgm ON player
    USING GIN (
        LOWER(coalesce(nullif(display_name, ''), name)) gin_trgm_ops
    );

CREATE TABLE archive_session (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name varchar(300) NOT NULL UNIQUE,
    match_date date,
    year smallint GENERATED ALWAYS AS (
        extract(year FROM match_date)::smallint
    ) STORED,
    month smallint GENERATED ALWAYS AS (
        extract(month FROM match_date)::smallint
    ) STORED,
    club_id uuid REFERENCES club(id),
    tournament boolean NOT NULL DEFAULT false,
    indexed_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX archive_session_year_month_idx ON archive_session (year, month);
CREATE INDEX archive_session_club_idx ON archive_session (club_id);
CREATE INDEX archive_session_date_idx ON archive_session (match_date);

CREATE TABLE match (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    session_id uuid REFERENCES archive_session(id) ON DELETE CASCADE,
    rel_path varchar(1000) NOT NULL UNIQUE,
    duration_seconds integer,
    size_mbytes integer NOT NULL,
    validation_error text,
    indexed_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX match_session_idx ON match (session_id);

CREATE TABLE match_player (
    match_id uuid NOT NULL REFERENCES match(id) ON DELETE CASCADE,
    player_id uuid NOT NULL REFERENCES player(id),
    position smallint NOT NULL,
    PRIMARY KEY (match_id, position)
);
CREATE INDEX match_player_player_idx ON match_player (player_id);

CREATE TABLE screenshot (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    match_id uuid NOT NULL REFERENCES match(id) ON DELETE CASCADE,
    timecode_seconds integer NOT NULL,
    image bytea NOT NULL,
    image_format varchar(10) NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    views bigint NOT NULL DEFAULT 0,
    created_at timestamp NOT NULL DEFAULT now()
);
CREATE INDEX screenshot_match_idx ON screenshot (match_id);

CREATE TABLE screenshot_like (
    screenshot_id uuid NOT NULL REFERENCES screenshot(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES app_user(id),
    created_at timestamp NOT NULL DEFAULT now(),
    PRIMARY KEY (screenshot_id, user_id)
);
CREATE INDEX screenshot_like_user_idx ON screenshot_like (user_id);
CREATE INDEX screenshot_like_screenshot_idx ON screenshot_like (screenshot_id);

CREATE TABLE screenshot_view (
    screenshot_id uuid NOT NULL REFERENCES screenshot(id) ON DELETE CASCADE,
    user_id uuid NOT NULL REFERENCES app_user(id),
    viewed_at timestamp NOT NULL DEFAULT now(),
    PRIMARY KEY (screenshot_id, user_id)
);
CREATE INDEX screenshot_view_user_idx ON screenshot_view (user_id);

ALTER TABLE archive_session ADD COLUMN IF NOT EXISTS type varchar(10) NOT NULL DEFAULT 'GAMES';
ALTER TABLE match ADD COLUMN IF NOT EXISTS type varchar(10) NOT NULL DEFAULT 'GAMES';

CREATE INDEX IF NOT EXISTS archive_session_type_idx ON archive_session (type);
CREATE INDEX IF NOT EXISTS match_type_idx ON match (type);
